import { Image } from 'react-native';

/** Liquid-metal textures of the « Métal » themes (generated by tools/make-metal.py). */
export const METAL_TEXTURES = {
  or: require('../../assets/metal/metal-or.jpg'),
  chrome: require('../../assets/metal/metal-chrome.jpg'),
} as const;

/** URL of a bundled image (web renderer). */
export function textureUri(source: number | { uri?: string } | string): string {
  if (typeof source === 'string') return source;
  if (typeof source === 'object' && source && 'uri' in source && source.uri) return source.uri;
  return Image.resolveAssetSource(source as number)?.uri ?? '';
}
